        load = 1;
        data = 10'd1;
        #1; if (tc !== 1'b0) begin errors = errors + 1; $display("Fail reloading from 0"); end

        // Cycle down: count goes from 1 to 0
        @(posedge clk);
        load = 0;
        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        @(posedge clk);
        #1; if (tc !== 1'b1) begin errors = errors + 1; end

        // Test 4: Reload *before* counting down to zero (interruptible count)
        @(posedge clk);
        load = 1;
        data = 10'd5;
        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        // Decrement once (count becomes 4)
        @(posedge clk);
        load = 0;
        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        // Reload mid-count with data = 2
        @(posedge clk);
        load = 1;
        data = 10'd2;
        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        // Decrement 1 (count becomes 1)
        @(posedge clk);
        load = 0;
        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        // Decrement 2 (count becomes 0, tc goes high)
        @(posedge clk);
        #1; if (tc !== 1'b1) begin errors = errors + 1; end

